import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"EmakiCodex","description":"","frontmatter":{},"headers":[],"relativePath":"modules/codex/index.md","filePath":"modules/codex/index.md","lastUpdated":null}'),c={name:"modules/codex/index.md"};function i(n,e,s,l,r,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="emakicodex" tabindex="-1">EmakiCodex <a class="header-anchor" href="#emakicodex" aria-label="Permalink to &quot;EmakiCodex&quot;">​</a></h1><p>EmakiCodex 是 Emaki 系列的原版成就图鉴模块。它通过 <code>advancements/*.yml</code> 定义成就页与节点，把节点注册为原版 Advancement，并支持命令、CoreLib Action、公开 API 与事件触发器授予或撤销节点。</p><p>安装 PacketEvents 时，EmakiCodex 会额外启用客户端成就树坐标注入与在线玩家重推能力；未安装 PacketEvents 时，成就仍会注册为原版 Advancement，但节点位置由客户端按 parent 树自动排布，在线玩家可能需要重新登录才能看到刚重载后的成就树变化。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.0.4</code></td></tr><tr><td>API Jar</td><td><code>emaki-codex-api-1.0.4.jar</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.codex.EmakiCodexPlugin</code></td></tr><tr><td>主命令</td><td><code>/codex</code></td></tr><tr><td>别名</td><td><code>/ecodex</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>PlaceholderAPI、PacketEvents、MythicMobs</td></tr><tr><td>最低服务端</td><td>Paper 1.21.8+（<code>api-version: 1.21.8</code>，<code>folia-supported: true</code>）</td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>主要权限</td><td><code>emakicodex.use</code>（默认 true）、<code>emakicodex.reload</code>（op）、<code>emakicodex.debug</code>（op）、<code>emakicodex.admin</code>（op）</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to &quot;功能页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/codex</code>、<code>/ecodex</code> 的可用子命令、权限和示例。</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 的全局开关与 <code>lang/*.yml</code> 语言文件。</td></tr><tr><td><a href="./advancements.html">成就页定义</a></td><td><code>advancements/*.yml</code> 的页面与节点字段、节点 key 规则、坐标规则与完成动作。</td></tr><tr><td><a href="./triggers.html">事件触发器</a></td><td><code>triggers.entries</code> 的写法、可用触发器变量与条件组示例。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>EmakiCodex 注册到 CoreLib ActionRegistry 的动作。</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td>第三方插件通过 <code>emaki-codex-api</code> 调用 Codex 的方式。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>原版 Advancement 图鉴</strong>：一个 <code>advancements/*.yml</code> 文件就是一个原版成就标签页，节点 key 形如 <code>emakicodex:&lt;page&gt;/&lt;node&gt;</code>。</li><li><strong>手动授予/撤销</strong>：管理员可用 <code>/codex grant</code> 与 <code>/codex revoke</code> 管理在线玩家节点进度。</li><li><strong>动作链授予</strong>：其他插件可在 CoreLib Action 中调用 <code>codex_grant_advancement</code>、<code>codex_revoke_advancement</code>、<code>codex_reset_page</code> 等 Codex 动作。</li><li><strong>事件触发器</strong>：节点可配置 <code>triggers.entries</code>，监听击杀、合成、熔炉取出、钓鱼、酿造、驯服、破坏方块、收割成熟作物等 CoreLib 共享 gameplay 事件。</li><li><strong>完成动作</strong>：节点完成后执行 <code>actions.complete</code> 中的 CoreLib Action，例如发送消息、发放奖励或触发其他模块逻辑。</li><li><strong>PacketEvents 坐标通道</strong>：安装 PacketEvents 且开启 <code>advancement.packet-coordinates</code> 时，节点 <code>x</code> / <code>y</code> 会写入客户端成就界面位置。</li></ul><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h2><p>服务器运行后，EmakiCodex 主要使用以下文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiCodex/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ advancements/</span></span>
<span class="line"><span>│  └─ example_page.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置，控制默认资源释放、Advancement 注册、PacketEvents 坐标注入和触发器总开关。</td></tr><tr><td><code>advancements/*.yml</code></td><td>成就页配置。每个文件定义一个页面、一个根节点和任意数量子节点。</td></tr><tr><td><code>lang/*.yml</code></td><td>命令、重载和控制台提示文本。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>把 <code>EmakiCoreLib-*.jar</code> 与 <code>EmakiCodex-*.jar</code> 放入服务器 <code>plugins/</code>。</li><li>不要把 <code>emaki-codex-api-*.jar</code> 放进服务器 <code>plugins/</code>；API Jar 只给开发者作为编译依赖使用。</li><li>首次启动后查看 <code>plugins/EmakiCodex/advancements/example_page.yml</code>。</li><li>修改或新增成就页后执行：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex reload</span></span></code></pre></div><ol start="5"><li>测试授予示例节点：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex grant Steve example/first_step</span></span></code></pre></div><p>完整 key 也可写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex grant Steve emakicodex:example/first_step</span></span></code></pre></div><h2 id="成就页配置速览" tabindex="-1">成就页配置速览 <a class="header-anchor" href="#成就页配置速览" aria-label="Permalink to &quot;成就页配置速览&quot;">​</a></h2><p>一个 <code>advancements/*.yml</code> 定义一个成就页：</p><ul><li>页面级：<code>page_id</code>（key 路径前缀）、<code>title</code>、<code>background</code>、<code>root</code>。</li><li>节点级：<code>icon</code>、<code>title</code>、<code>description</code>、<code>frame</code>、<code>parent</code>、<code>x</code> / <code>y</code>、<code>toast</code>、<code>announce</code>、<code>hidden</code>。</li><li>节点完成动作写在 <code>actions.complete</code>，事件触发器写在 <code>triggers.entries</code>。触发条件使用 CoreLib 标准条件组：<code>condition.type</code> + <code>condition.entries</code>。</li></ul><p>节点会注册为 <code>emakicodex:&lt;page_id&gt;/&lt;node_id&gt;</code>。完整字段表、key 规则与坐标规则见<a href="./advancements.html">成就页定义</a>，触发器变量与条件组示例见<a href="./triggers.html">事件触发器</a>。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to &quot;使用提示&quot;">​</a></h2><ul><li>EmakiCodex 当前聚焦原版成就图鉴，不再提供配方/JEI 传递功能。</li><li>节点完成条件统一由 Codex 授予：命令、Action、公开 API 或触发器会奖励内部 <code>codex</code> criterion。</li><li><code>actions.complete</code> 只会在节点首次完成时触发；重复授予已完成节点不会重复执行完成动作。</li><li>如果开启坐标，建议同一成就页全部节点都配置 <code>x</code> / <code>y</code>，避免“部分显式坐标 + 部分自动排布”导致重叠。</li></ul>`,26)])])}const x=t(c,[["render",i]]);export{m as __pageData,x as default};
